## Why This Is Asked

Tests ability to design an order-statistics structure with duplicates using a compact, well-known DS (Fenwick). Requires handling inserts, deletes, and k-th retrieval within tight bounds.

## Key Concepts

- Coordinate compression to bound domain size
- Fenwick Tree for prefix sums (counts)
- getKthSmallest via binary lifting on Fenwick
- Handling duplicates and safe deletes
- Time: O(log m) per operation, m distinct values

## Code Example

```javascript
class Fenwick {
  constructor(n){ this.n=n; this.f=new Array(n+1).fill(0); }
  add(i, delta){ for(; i<=this.n; i+= i&-i) this.f[i]+=delta; }
  sum(i){ let s=0; for(; i>0; i-= i&-i) s+=this.f[i]; return s; }
  kth(k){
    let idx=0; let bit=1;
    while((bit<<1) <= this.n) bit <<= 1;
    for(let step=bit; step>0; step>>=1){
      const t = idx+step;
      if(t<=this.n && this.f[t] < k){
        idx = t;
        k -= this.f[t];
      }
    }
    return idx+1;
  }
}
class KthMultiset {
  constructor(vals){
    this.values = Array.from(new Set(vals)).sort((a,b)=>a-b);
    this.index = new Map(this.values.map((v,i)=>[v,i+1]));
    this.ft = new Fenwick(this.values.length);
  }
  add(x){ const i = this.index.get(x); if(i) this.ft.add(i, 1); }
  remove(x){ const i = this.index.get(x); if(i) this.ft.add(i, -1); }
  getKthSmallest(k){ const idx = this.ft.kth(k); return this.values[idx-1]; }
}
```

## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

